with target as(select isbn13,content_hash,candidate||jsonb_build_object('cover_url','https://dvs-cover.kodansha.co.jp/0000047917/tR86b66YJo0rFgvrQahpN1wdbDpfJ6fw3cyIx7pQ.jpg','cover_hash','bd7d19fdfa7e011204cc814b054ce414f1a497870c2f72ba028a7f1f08980ead','source_url','https://www.kodansha.co.jp/comic/products/0000047917','cover_reference_before_correction',jsonb_build_object('cover_url',candidate->>'cover_url','cover_hash',candidate->>'cover_hash','source_url',candidate->>'source_url')) as new_candidate from public.book_content_review_jobs where isbn13='9784063925159' and content_hash='b9da96c85286873d81547f91bc7f64a912492a00365598f5dd2ec4a80aeb5a19' and adult_only is null and status='pending_review' and cover_status='unreviewed'),fixed as(update public.book_content_review_jobs j set candidate=t.new_candidate,content_hash=encode(sha256(convert_to(t.new_candidate::text,'UTF8')),'hex'),reason='文字のみの代替画像を、ISBN一致の講談社公式通常版表紙へ修正。分類・公開許可は維持。',updated_at=now() from target t where j.isbn13=t.isbn13 and j.content_hash=t.content_hash returning j.isbn13,j.candidate),confirmed as(insert into public.book_metadata_overrides(isbn,normalized_isbn,title,series_title,series_key,volume_number,author,publisher,description,thumbnail_url,source_url,source,enabled) select isbn13,isbn13,'ノラガミ 16','ノラガミ','ノラガミ',16,'あだちとか','講談社',candidate->>'description','https://dvs-cover.kodansha.co.jp/0000047917/tR86b66YJo0rFgvrQahpN1wdbDpfJ6fw3cyIx7pQ.jpg','https://www.kodansha.co.jp/comic/products/0000047917','developer',true from fixed on conflict(normalized_isbn) where normalized_isbn is not null do nothing returning normalized_isbn) select (select count(*) from fixed) as corrected,(select count(*) from confirmed) as confirmed;
